172	/**
173	 * @brief Enable the bus clock for SDIO PLL
174	 *
175	 * @param hw    hardware instance address
176	 * @param en    enable / disable
177	 */
178	static inline void sdmmc_ll_enable_sdio_pll(sdmmc_dev_t *hw, bool en)
179	{
180	    if (en) {
181	        REG_SET_BIT(PMU_RF_PWC_REG, PMU_SDIO_PLL_XPD);
182	        REG_SET_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_XPD_SDIOPLL_I2C);
183	        REG_SET_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_XPD_SDIOPLL);
184	        REG_SET_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_GLOBAL_SDIOPLL_ICG);
185	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll0_clk_en = 1;
186	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll1_clk_en = 1;
187	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll2_clk_en = 1;
188	    } else {
189	        REG_CLR_BIT(PMU_RF_PWC_REG, PMU_SDIO_PLL_XPD);
190	        REG_CLR_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_XPD_SDIOPLL_I2C);
191	        REG_CLR_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_XPD_SDIOPLL);
192	        REG_CLR_BIT(PMU_IMM_HP_CK_POWER_REG, PMU_TIE_HIGH_GLOBAL_SDIOPLL_ICG);
193	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll0_clk_en = 0;
194	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll0_clk_en = 0;
195	        LP_AON_CLKRST.hp_clk_ctrl.hp_sdio_pll2_clk_en = 0;
196	    }
197	}
